def triples_sum_to_zero(l: list):
    nums = sorted(l)
    n = len(nums)

    for i in range(n - 2):
        j = i + 1
        k = n - 1

        while j < k:
            total = nums[i] + nums[j] + nums[k]

            if total == 0:
                return True
            elif total < 0:
                j += 1
            else:
                k -= 1

    return False
