def get_max_triples(n):
    full, rem = divmod(n, 3)
    zeros = full + (1 if rem >= 2 else 0)
    ones = n - zeros

    def comb3(x):
        return x * (x - 1) * (x - 2) // 6 if x >= 3 else 0

    return comb3(zeros) + comb3(ones)
